const b = $json.body || $json;
const p = b.property || b;
const l = b.lead || {};
const distress = Array.isArray(p.distress_markers) ? p.distress_markers.map(x => String(x).toLowerCase()) : [];
const value = Number(p.after_repair_value || p.estimated_value || 0);
const repairs = Number(p.repair_estimate || 0);
const ask = Number(p.asking_price || 0);
const equity = Number(p.equity || 0);
const assignmentFee = Number(p.assignment_fee_target || 0);
const buyerMaxAllInPercent = Number(p.buyer_max_all_in_percent || 0);
const buyerProfitTarget = Number(p.buyer_profit_target || 0);
const transactionCosts = Number(p.transaction_costs || 0);
const holdingCosts = Number(p.holding_costs || 0);
const financingCosts = Number(p.financing_costs || 0);
const riskBuffer = Number(p.risk_buffer || 0);

let score = 0; const factors = [];
const distressWeights = {pre_foreclosure:10,tax_delinquent:8,probate:8,code_violation:7,vacant:6,absentee_owner:5,tired_landlord:5,high_equity:5,distressed:8,vacant_land:5};
let distressScore = 0; for (const d of distress) distressScore += distressWeights[d] || 2; distressScore = Math.min(30, distressScore); score += distressScore; if (distressScore) factors.push({name:'distress',points:distressScore});
let equityScore = 0; if (equity > 0 && value > 0) equityScore = Math.min(20, Math.max(0, (equity/value)*20)); else if (String(l.equity_level||'').toLowerCase()==='high') equityScore=15; score += equityScore; if(equityScore) factors.push({name:'equity',points:Math.round(equityScore*10)/10});
let priceScore=0, priceRatio=null; if(ask>0 && value>0){priceRatio=ask/value; priceScore=Math.max(0,Math.min(20,(0.95-priceRatio)*133.33)); score+=priceScore; factors.push({name:'price_to_value',points:Math.round(priceScore*10)/10);}
let rehabScore=0; if(value>0 && repairs>0) rehabScore=Math.min(10,(repairs/value)*20); else if(String(p.condition||'').toLowerCase().match(/poor|fair|distressed|major/)) rehabScore=6; score+=rehabScore; if(rehabScore) factors.push({name:'rehab_signal',points:Math.round(rehabScore*10)/10});
let contactScore=0; if(l.phone && !l.do_not_contact) contactScore=5; else if(l.email && !l.do_not_contact) contactScore=3; score+=contactScore; if(contactScore) factors.push({name:'contactability',points:contactScore});
let marketScore=0; const targetCities=new Set(['hickory','charlotte','raleigh','wilmington']); if(targetCities.has(String(p.city||'').toLowerCase())) marketScore=5; score+=marketScore; if(marketScore) factors.push({name:'target_market',points:marketScore});

let underwriting=null;
if (value > 0) {
  const benchmarkMao = (value * 0.70) - repairs;
  const explicitBuyerCeiling = buyerMaxAllInPercent > 0 ? value * (buyerMaxAllInPercent > 1 ? buyerMaxAllInPercent / 100 : buyerMaxAllInPercent) : null;
  const buyerEconomicsCeiling = explicitBuyerCeiling !== null
    ? explicitBuyerCeiling
    : value - (transactionCosts || value * 0.05) - (holdingCosts || value * 0.04) - (financingCosts || value * 0.03) - (riskBuffer || value * 0.03) - (buyerProfitTarget || value * 0.10);
  const buyerPurchaseCeiling = Math.max(0, buyerEconomicsCeiling - repairs);
  const sellerContractCeiling = Math.max(0, buyerPurchaseCeiling - assignmentFee);
  const baseMao = sellerContractCeiling;
  const spread = ask > 0 ? baseMao - ask : null;
  const dealViable = ask > 0 ? spread >= 0 : true;
  underwriting = {
    strategy:p.mao_strategy || 'flip',
    benchmark_70_percent:Math.round(Math.max(0,benchmarkMao)*100)/100,
    buyer_max_all_in:Math.round(buyerEconomicsCeiling*100)/100,
    buyer_purchase_ceiling:Math.round(buyerPurchaseCeiling*100)/100,
    seller_contract_ceiling:Math.round(sellerContractCeiling*100)/100,
    estimated_spread:spread === null ? null : Math.round(spread*100)/100,
    deal_viable:dealViable,
    method:explicitBuyerCeiling !== null ? 'buyer_buy_box' : 'buyer_economics',
    assumptions:{
      transaction_costs:Math.round((transactionCosts || value*0.05)*100)/100,
      holding_costs:Math.round((holdingCosts || value*0.04)*100)/100,
      financing_costs:Math.round((financingCosts || value*0.03)*100)/100,
      risk_buffer:Math.round((riskBuffer || value*0.03)*100)/100,
      buyer_profit_target:Math.round((buyerProfitTarget || value*0.10)*100)/100,
      repairs:Math.round(repairs*100)/100,
      assignment_fee:Math.round(assignmentFee*100)/100
    }
  };
  if (dealViable) {
    score += 10;
    factors.push({name:'buyer_economics_viability',points:10});
  } else {
    score -= 5;
    factors.push({name:'buyer_economics_gap',points:-5});
  }
}
score=Math.round(Math.min(100,Math.max(0,score)));
let action=score>=75?'pursue_now':score>=55?'review_and_contact':score>=35?'nurture':'low_priority';
if(l.do_not_contact) action='do_not_contact';
if(underwriting && underwriting.deal_viable === false && action === 'pursue_now') action='review_and_contact';

const result={opportunity_score:score,action,score_factors:factors,arv:value||null,repair_estimate:repairs||null,asking_price:ask||null,underwriting,scored_at:new Date().toISOString(),scoring_version:'nc-v2-adaptive-mao'};
return [{json:{lead_id:Number(b.lead_id||l.id||0),property_id:Number(b.property_id||p.id||0),score:result}}];
